import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/animal-protection/behaviour-and-senses/","title":"CH3.6 行为、感知与本能 | 英语","lang":"zh-CN","frontmatter":{"title":"CH3.6 行为、感知与本能","createTime":"2026-11-20T10:00:00.000Z","permalink":"/english/vocabulary/animal-protection/behaviour-and-senses/"},"readingTime":{"minutes":32.42,"words":9725},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/animal-protection/6.behaviour-and-senses.md","headers":[],"bulletin":false}`),a={name:`6.behaviour-and-senses.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="behaviour" tabindex="-1"><a class="header-anchor" href="#behaviour"><span>Behaviour</span></a></h2><p class="vc-meta"><strong>/bɪˈheɪvjə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>行为，举止（人或动物的）</li><li>（事物的）表现、反应方式（英式拼写 behaviour，美式 behavior）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>animal behaviour</td><td>动物行为</td></tr><tr><td>behaviour patterns</td><td>行为模式</td></tr><tr><td>change its behaviour</td><td>改变行为</td></tr><tr><td>aggressive behaviour</td><td>攻击性行为</td></tr><tr><td>be on one&#39;s best behaviour</td><td>表现得规规矩矩</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the feeding behaviour of the two species at different times of day.</p><blockquote><p>该图比较了两个物种在一天中不同时段的取食行为。</p></blockquote><p><strong>Writing Task 2</strong> Feeding wild animals alters their behaviour in ways that are rarely reversible: once they associate people with food, the association is permanent.</p><blockquote><p>投喂野生动物会以几乎不可逆的方式改变它们的行为：一旦把人和食物联系起来，这种联系就是永久的。</p></blockquote><p><strong>Speaking</strong> The behaviour of the pigeons in this square is basically organised crime.</p><blockquote><p>这个广场上鸽子的行为基本属于有组织犯罪。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>conduct</td><td>行为举止</td><td>正式，多用于人的社会行为</td></tr><tr><td>manner</td><td>方式；举止</td><td>强调具体做法</td></tr><tr><td>habit</td><td>习惯</td><td>强调重复性，不指单次反应</td></tr><tr><td>response</td><td>反应</td><td>强调对外部刺激的回应</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> be-（加强）+ have（持有）→ &quot;把自己持守成某种样子&quot;</li><li><strong>Family:</strong> behave 表现 / behavioural 行为的 / behaviourism 行为主义 / misbehave 行为不端</li><li><strong>Memory Tip:</strong> behaviour 的核心是 have——&quot;一个人持守的样子&quot;。英式拼写多一个 u（behaviour），与 colour、favour 同一规律，整套词一起记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>behaviours</s> 一般不用于泛指；指&quot;多种具体行为&quot;时学术文本可数。</li><li>英式 behaviour、美式 behavior，同一篇里要统一。</li><li>动物行为学是 <strong>ethology</strong>，不是 <s>behaviourology</s>。</li></ul></div><div class="vocab-card"><h2 id="instinct" tabindex="-1"><a class="header-anchor" href="#instinct"><span>Instinct</span></a></h2><p class="vc-meta"><strong>/ˈɪnstɪŋkt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>本能，天性</li><li>直觉（尤指难以解释的）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>by instinct</td><td>出于本能</td></tr><tr><td>animal instinct</td><td>动物本能</td></tr><tr><td>a strong instinct</td><td>强烈的本能</td></tr><tr><td>trust your instincts</td><td>相信直觉</td></tr><tr><td>the instinct to ...</td><td>……的本能</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a newly hatched turtle follows an instinct rather than any learned behaviour.</p><blockquote><p>该示意图展示了刚孵出的海龟如何凭本能而非习得行为行动。</p></blockquote><p><strong>Writing Task 2</strong> Migration is usually described as instinct, yet young birds often learn the route from adults, which makes the behaviour far more fragile than it appears.</p><blockquote><p>迁徙通常被描述为本能，但幼鸟常常从成鸟那里学习路线，这使该行为比看起来脆弱得多。</p></blockquote><p><strong>Speaking</strong> My first instinct was to run, and for once I was right.</p><blockquote><p>我的第一反应是跑，这一次我难得的对了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>intuition</td><td>直觉</td><td>多用于人的判断，不含生物机制</td></tr><tr><td>impulse</td><td>冲动</td><td>强调一时的驱动，非固有能力</td></tr><tr><td>drive</td><td>内驱力</td><td>心理学术语，指推动力</td></tr><tr><td>reflex</td><td>反射</td><td>生理性的即时反应，不涉判断</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> in-（在内）+ 拉丁 <em>stinguere</em>（刺激）→ &quot;内在的刺激&quot;</li><li><strong>Family:</strong> instinctive 本能的 / instinctively 本能地 / distinct 不同的（同源&quot;刺出&quot;）/ extinguish 熄灭</li><li><strong>Memory Tip:</strong> 词根 stinguere 是&quot;刺&quot;——本能就是&quot;从里面刺你一下&quot;的那股力量，不用想就动。同族的 distinct 是&quot;被刺出来、区分开&quot;，一源两义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 <strong>instinctive</strong>：an instinctive <strong>reaction</strong> ✔ / <s>an instinct reaction</s> ✘</li><li>&quot;出于本能&quot;是 <strong>by instinct</strong>，不加冠词。</li><li>拼写 inst-inct，注意中间没有 <s>-stinc-</s> 之外的变化。</li></ul></div><div class="vocab-card"><h2 id="intuitive" tabindex="-1"><a class="header-anchor" href="#intuitive"><span>Intuitive</span></a></h2><p class="vc-meta"><strong>/ɪnˈtjuːɪtɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>直觉的，凭直觉的</li><li>易懂的，符合直觉的（设计、界面）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an intuitive understanding</td><td>直觉性的理解</td></tr><tr><td>intuitive knowledge</td><td>直觉知识</td></tr><tr><td>intuitive design</td><td>符合直觉的设计</td></tr><tr><td>intuitive judgement</td><td>直觉判断</td></tr><tr><td>counter-intuitive</td><td>反直觉的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows a device designed to be intuitive for users with no training.</p><blockquote><p>该示意图展示了一种为未经培训的使用者设计的、符合直觉的装置。</p></blockquote><p><strong>Writing Task 2</strong> Much of what animals know is intuitive rather than taught, which is why isolating a young animal from its kind rarely produces normal behaviour.</p><blockquote><p>动物所知的许多内容是直觉性的而非教出来的，因此把幼兽与同类隔离很少能产生正常行为。</p></blockquote><p><strong>Speaking</strong> The controls look complicated but they&#39;re actually quite intuitive once you try them.</p><blockquote><p>这些操控看着复杂，其实一试就懂。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>instinctive</td><td>本能的</td><td>强调生物性驱动，不涉&quot;易懂&quot;</td></tr><tr><td>innate</td><td>天生的</td><td>强调与生俱来，非后天习得</td></tr><tr><td>natural</td><td>自然的</td><td>最泛，缺乏&quot;无需推理&quot;的精确义</td></tr><tr><td>self-evident</td><td>不言自明的</td><td>强调无需证明，语气更强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> in-（向内）+ 拉丁 <em>tueri</em>（看）→ &quot;向内看&quot;→ 直觉</li><li><strong>Family:</strong> intuition 直觉 / intuit 凭直觉感到 / tuition 教学（同源&quot;照看&quot;）/ tutor 导师</li><li><strong>Memory Tip:</strong> 词根 tueri 是&quot;看护、注视&quot;。intuition 是&quot;往内看自己&quot;，tuition 是&quot;有人照看你学习&quot;——同一个&quot;看&quot;，两种方向。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 intuit-ive，注意中间是 -uit-，不要写成 <s>intuative</s>。</li><li>&quot;反直觉的&quot;是 <strong>counter-intuitive</strong>，带连字符。</li><li>形容词修饰&quot;人&quot;时意思是&quot;有直觉力的&quot;，修饰事物才是&quot;易懂的&quot;，语境要看。</li></ul></div><div class="vocab-card"><h2 id="potential" tabindex="-1"><a class="header-anchor" href="#potential"><span>Potential</span></a></h2><p class="vc-meta"><strong>/pəˈtenʃl/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>潜在的，可能的（形容词）</li><li>潜力，潜能；电势（名词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>potential threat</td><td>潜在威胁</td></tr><tr><td>reach one&#39;s potential</td><td>发挥潜力</td></tr><tr><td>the potential to ...</td><td>……的可能性</td></tr><tr><td>potential impact</td><td>潜在影响</td></tr><tr><td>realise its potential</td><td>实现其潜能</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the potential yield of the four crops under irrigation.</p><blockquote><p>该图显示了四种作物在灌溉条件下的潜在产量。</p></blockquote><p><strong>Writing Task 2</strong> Every introduced species carries the potential to become invasive, though only a small fraction ever does.</p><blockquote><p>每个外来物种都带有成为入侵物种的潜在可能，尽管真正如此的只是很小一部分。</p></blockquote><p><strong>Speaking</strong> That dog has the potential to be a great pet, but right now it&#39;s a menace.</p><blockquote><p>那只狗有成为好宠物的潜力，但现在完全是个祸害。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>possible</td><td>可能的</td><td>只表可能性，不含&quot;待开发&quot;义</td></tr><tr><td>latent</td><td>潜伏的</td><td>学术，强调存在但未显现</td></tr><tr><td>capacity</td><td>容量；能力</td><td>强调可承载的量，非前景</td></tr><tr><td>prospect</td><td>前景</td><td>名词，多指未来的机会</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>potentia</em>（力量），源自 <em>posse</em>（能够）</li><li><strong>Family:</strong> potent 强效的 / potential 潜在的 / potency 效力 / omnipotent 全能的</li><li><strong>Memory Tip:</strong> 词根 posse 是&quot;能&quot;：potential（尚未发挥的能）、potent（已经很有效）。一句 &quot;the potential to become potent&quot; 就把两者串起来。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作形容词只作定语：potential <strong>risk</strong> ✔ / <s>The risk is potential.</s>（宜改 possible）</li><li>名词不可数，通常不加 a：<strong>potential</strong> for growth ✔（a potential 少见）</li><li>拼写 poten-tial，注意 -tial 不是 <s>-cial</s>。</li></ul></div><div class="vocab-card"><h2 id="intelligence" tabindex="-1"><a class="header-anchor" href="#intelligence"><span>Intelligence</span></a></h2><p class="vc-meta"><strong>/ɪnˈtelɪdʒəns/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>智力，智能；理解力</li><li>情报；情报机构</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>animal intelligence</td><td>动物智力</td></tr><tr><td>artificial intelligence</td><td>人工智能</td></tr><tr><td>a test of intelligence</td><td>智力测验</td></tr><tr><td>high intelligence</td><td>高智力</td></tr><tr><td>intelligence gathering</td><td>情报收集</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the performance of four species on a standard intelligence test.</p><blockquote><p>该图比较了四个物种在标准智力测验中的表现。</p></blockquote><p><strong>Writing Task 2</strong> Judging animal intelligence by human standards is misleading, since a crow that solves a puzzle and a dolphin that recognises itself are demonstrating quite different abilities.</p><blockquote><p>用人类标准衡量动物智力会产生误导，因为解谜的乌鸦与能认出镜中自己的海豚展示的是相当不同的能力。</p></blockquote><p><strong>Speaking</strong> Octopuses have frightening intelligence — one in a tank can learn your face and hold a grudge.</p><blockquote><p>章鱼的智力有点吓人，水缸里那只记得你的脸，还会记仇。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>intellect</td><td>智力</td><td>偏人的理性能力，较正式</td></tr><tr><td>cognition</td><td>认知</td><td>学术，指全部信息加工过程</td></tr><tr><td>wit</td><td>机智</td><td>强调机敏与口才</td></tr><tr><td>brainpower</td><td>脑力</td><td>口语，集体概念</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> inter-（之间）+ 拉丁 <em>legere</em>（选择、读）→ &quot;在事物之间做选择的能力&quot;</li><li><strong>Family:</strong> intelligent 聪明的 / intelligible 可理解的 / intellect 智力 / legend 传说（同源&quot;可读之物&quot;）</li><li><strong>Memory Tip:</strong> legere 是&quot;读、选&quot;：intelligence 是&quot;能在事物间读出关系&quot;；同族的 legend 原义&quot;该被读的东西&quot;。一条词根连起&quot;聪明&quot;与&quot;传说&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 <strong>intelligent</strong>：an intelligent <strong>animal</strong> ✔ / <s>an intelligence animal</s> ✘</li><li>不可数：<s>intelligences</s> 一般不用（&quot;多种智能&quot;属心理学的特殊用法）。</li><li>AI 的全称是 <strong>artificial intelligence</strong>，缩写 AI，正式文本首次出现要写全。</li></ul></div><div class="vocab-card"><h2 id="functional" tabindex="-1"><a class="header-anchor" href="#functional"><span>Functional</span></a></h2><p class="vc-meta"><strong>/ˈfʌŋkʃənl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>功能的，功能性的</li><li>实用的，能正常工作的</li><li>官能的（医学）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>functional adaptation</td><td>功能性适应</td></tr><tr><td>fully functional</td><td>功能完好</td></tr><tr><td>functional design</td><td>实用设计</td></tr><tr><td>functional extinction</td><td>功能性灭绝</td></tr><tr><td>a functional response</td><td>功能性反应</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the functional parts of a bird&#39;s wing and what each contributes to flight.</p><blockquote><p>该示意图展示了鸟翼的各功能部位及各自对飞行的贡献。</p></blockquote><p><strong>Writing Task 2</strong> A species can be functionally extinct long before the last individual dies: if no pair remains, the population is already over.</p><blockquote><p>一个物种可能在最后一个个体死亡之前很久就已功能性灭绝：若不再有成对的个体，这个种群其实已经结束。</p></blockquote><p><strong>Speaking</strong> The app is functional, but it looks like it was designed in 2004.</p><blockquote><p>这个应用功能是齐的，但看起来像 2004 年设计的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>practical</td><td>实用的</td><td>强调好用，不涉功能分类</td></tr><tr><td>operational</td><td>运行中的</td><td>强调设备在运转</td></tr><tr><td>utilitarian</td><td>功利实用的</td><td>带&quot;只求有用、不讲美观&quot;意味</td></tr><tr><td>working</td><td>可用的</td><td>口语，最简</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> funct-（拉丁 <em>fungi</em>，履行）+ -ion + -al</li><li><strong>Family:</strong> function 功能 / malfunction 故障 / defunct 不再使用的 / perfunctory 敷衍的</li><li><strong>Memory Tip:</strong> &quot;功能性灭绝&quot;（functional extinction）是保护生物学的核心概念——数量少到无法再发挥生态作用。抓住这个术语，functional 的&quot;功能&quot;核心义就不会跑偏。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 funct-ional，注意 -tion- 不能省成 <s>funtional</s>。</li><li>functional ≠ functioning：前者&quot;具备功能/实用的&quot;，后者&quot;正在运转的&quot;。</li><li>副词是 <strong>functionally</strong>：functionally <strong>extinct</strong> ✔</li></ul></div><div class="vocab-card"><h2 id="sensitive" tabindex="-1"><a class="header-anchor" href="#sensitive"><span>Sensitive</span></a></h2><p class="vc-meta"><strong>/ˈsensətɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>敏感的，易受影响的</li><li>体贴的，善解人意的</li><li>机密的，需谨慎处理的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>sensitive to ...</td><td>对……敏感</td></tr><tr><td>highly sensitive</td><td>高度敏感</td></tr><tr><td>a sensitive habitat</td><td>敏感栖息地</td></tr><tr><td>sensitive information</td><td>机密信息</td></tr><tr><td>sensitive skin</td><td>敏感肌肤</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how sensitive each species is to changes in water temperature.</p><blockquote><p>该图显示了各物种对水温变化的敏感程度。</p></blockquote><p><strong>Writing Task 2</strong> Coral reefs are so sensitive to heat that a rise of one degree sustained for a few weeks can trigger mass bleaching.</p><blockquote><p>珊瑚礁对高温极为敏感，持续数周升高一度就足以引发大规模白化。</p></blockquote><p><strong>Speaking</strong> My skin is sensitive to everything, which makes buying soap a research project.</p><blockquote><p>我的皮肤对什么都敏感，买块肥皂都像做研究。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vulnerable</td><td>易受损的</td><td>强调承受伤害，不指&quot;感知灵敏&quot;</td></tr><tr><td>responsive</td><td>反应灵敏的</td><td>中性偏褒，强调反应快</td></tr><tr><td>delicate</td><td>娇弱的</td><td>强调脆弱、需小心</td></tr><tr><td>susceptible</td><td>易感的</td><td>学术，多指易患病</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> sens-（拉丁 <em>sentire</em>，感觉）+ -itive</li><li><strong>Family:</strong> sense 感觉 / sensory 感觉的 / sensation 感觉；轰动 / insensitive 迟钝的</li><li><strong>Memory Tip:</strong> sens- 是&quot;感觉&quot;：sensitive 敏感、sensory 感官的、sensation 感觉。加否定前缀 in- 变成&quot;不敏感&quot;，一组四个词一次收。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 <strong>to</strong>：sensitive <strong>to</strong> light ✔ / <s>sensitive for light</s> ✘</li><li>形容人&quot;sensitive&quot;是&quot;体贴的&quot;或&quot;易受伤的&quot;，含义取决于语境，切勿一概译成&quot;敏感&quot;。</li><li>拼写 sens-itive，不是 <s>sensitve</s>。</li></ul></div><div class="vocab-card"><h2 id="flexible" tabindex="-1"><a class="header-anchor" href="#flexible"><span>Flexible</span></a></h2><p class="vc-meta"><strong>/ˈfleksəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>柔韧的，易弯曲的</li><li>灵活的，可变通的（计划、人）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a flexible body</td><td>柔韧的身体</td></tr><tr><td>flexible working hours</td><td>弹性工作时间</td></tr><tr><td>remain flexible</td><td>保持灵活</td></tr><tr><td>a flexible approach</td><td>灵活的做法</td></tr><tr><td>flexible joints</td><td>可弯曲的关节</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram compares the flexible spine of a snake with the rigid spine of a fish.</p><blockquote><p>该示意图比较了蛇柔韧的脊柱与鱼僵直的脊柱。</p></blockquote><p><strong>Writing Task 2</strong> Animals with a flexible diet survive habitat change far better than specialists that depend on a single food source.</p><blockquote><p>食谱灵活的动物在栖息地变化中存活得远好于依赖单一食物的专食者。</p></blockquote><p><strong>Speaking</strong> My schedule is fairly flexible, so any time after ten works for me.</p><blockquote><p>我的时间比较灵活，十点以后都行。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>pliable</td><td>易弯的</td><td>强调材料柔软可塑</td></tr><tr><td>adaptable</td><td>适应性强的</td><td>强调能调整自身以应对变化</td></tr><tr><td>elastic</td><td>有弹性的</td><td>强调拉伸后回弹</td></tr><tr><td>versatile</td><td>多用途的</td><td>强调功能多样，非形态柔韧</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>flectere</em>（弯曲）+ -ible（能……的）</li><li><strong>Family:</strong> flex 弯曲；屈伸 / flexibility 灵活性 / deflect 偏转 / reflect 反射</li><li><strong>Memory Tip:</strong> flectere 是&quot;弯&quot;：flexible 能弯的、deflect 弯开（偏转）、reflect 弯回（反射）。一条词根带出三个高频词，方向感很清楚。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 flex-ible，不是 <s>flexable</s>。</li><li>名词是 <strong>flexibility</strong>：<s>flexibleness</s> 极少用。</li><li>说&quot;时间灵活&quot;用 flexible，不用 <s>free</s>（后者指&quot;有空&quot;）。</li></ul></div><div class="vocab-card"><h2 id="acoustic" tabindex="-1"><a class="header-anchor" href="#acoustic"><span>Acoustic</span></a></h2><p class="vc-meta"><strong>/əˈkuːstɪk/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>声音的，声学的</li><li>（乐器）原声的，非电子的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>acoustic signals</td><td>声信号</td></tr><tr><td>acoustic communication</td><td>声音交流</td></tr><tr><td>an acoustic guitar</td><td>原声吉他</td></tr><tr><td>acoustic pollution</td><td>噪声污染</td></tr><tr><td>acoustic properties</td><td>声学特性</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how an acoustic signal travels through water and where it is detected.</p><blockquote><p>该示意图展示了声信号如何在水下传播以及在哪里被接收。</p></blockquote><p><strong>Writing Task 2</strong> Whales communicate over hundreds of kilometres, but shipping noise now masks the acoustic signals they depend on.</p><blockquote><p>鲸能在数百公里范围内交流，但航运噪声如今掩盖了它们赖以生存的声信号。</p></blockquote><p><strong>Speaking</strong> The venue is beautiful but acoustically terrible — everything echoes for two seconds.</p><blockquote><p>场地很漂亮，但声学效果极差，什么声音都要回响两秒。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sonic</td><td>声音的</td><td>多用于速度（sonic boom）</td></tr><tr><td>auditory</td><td>听觉的</td><td>强调感知器官，不指物理传播</td></tr><tr><td>audio</td><td>音频的</td><td>指设备与信号格式</td></tr><tr><td>sound</td><td>声音</td><td>通用词，非术语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>akouein</em>（听）</li><li><strong>Family:</strong> acoustics 声学 / acoustic 声学的 / otolaryngology 耳鼻喉科（同源&quot;听&quot;）</li><li><strong>Memory Tip:</strong> 词根 akouein 是&quot;听&quot;——acoustic 就是&quot;关于听的&quot;。原声吉他是 acoustic guitar，因为不靠电，全靠空气传声。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>学科名 <strong>acoustics</strong> 作&quot;声学&quot;时用单数谓语。</li><li>拼写 acou-stic，注意 -ou- 不是 <s>-oo-</s>。</li><li>&quot;原声吉他&quot;是 acoustic guitar，不是 <s>unplugged guitar</s>（后者指不插电演出）。</li></ul></div><div class="vocab-card"><h2 id="optical" tabindex="-1"><a class="header-anchor" href="#optical"><span>Optical</span></a></h2><p class="vc-meta"><strong>/ˈɒptɪkl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>光学的，视觉的</li><li>（眼镜）光学的；视觉矫正的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>optical illusion</td><td>视错觉</td></tr><tr><td>optical instrument</td><td>光学仪器</td></tr><tr><td>optical fibres</td><td>光纤</td></tr><tr><td>the optic nerve</td><td>视神经</td></tr><tr><td>an optical response</td><td>视觉反应</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the optical structure of the insect&#39;s eye and how images are formed.</p><blockquote><p>该示意图展示了昆虫眼的光学结构以及图像如何形成。</p></blockquote><p><strong>Writing Task 2</strong> Many animals rely on optical signals — colour, pattern, movement — that humans cannot even perceive, which makes &quot;invisible&quot; damage to habitats easy to overlook.</p><blockquote><p>许多动物依赖人类甚至无法察觉的光学信号——颜色、图案、运动，这使对栖息地的&quot;看不见的&quot;损害容易被忽视。</p></blockquote><p><strong>Speaking</strong> The floor pattern is a deliberate optical illusion and I&#39;ve watched three people trip on it.</p><blockquote><p>地板图案是故意的视错觉，我已经看见三个人在上面绊倒。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>visual</td><td>视觉的</td><td>强调&quot;与看有关&quot;，不涉物理光学</td></tr><tr><td>optic</td><td>光学的</td><td>多用于解剖（optic nerve）</td></tr><tr><td>photographic</td><td>摄影的</td><td>指成像方式</td></tr><tr><td>ocular</td><td>眼的</td><td>医学用语，强调眼球本身</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>optikos</em>（看的），源自 <em>ops</em>（眼）</li><li><strong>Family:</strong> optics 光学 / optician 验光师 / optical 光学的 / opt 选择（同源&quot;看准&quot;）</li><li><strong>Memory Tip:</strong> opt- 是&quot;看&quot;：optical 光学的、optician 验光师、opt 选择（看清后决定）。&quot;视错觉&quot;optical illusion 是最常见的搭配，可作锚点。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 op-tical，不是 <s>optcial</s>。</li><li>optical（光学的）与 visual（视觉的）不完全互换：optical illusion 固定搭配。</li><li>副词 <strong>optically</strong>：optically <strong>active</strong> ✔</li></ul></div><div class="vocab-card"><h2 id="nocturnal" tabindex="-1"><a class="header-anchor" href="#nocturnal"><span>Nocturnal</span></a></h2><p class="vc-meta"><strong>/nɒkˈtɜːnl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>夜行的，夜间活动的</li><li>夜间的，夜间发生的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>nocturnal animals</td><td>夜行动物</td></tr><tr><td>nocturnal habits</td><td>夜行习性</td></tr><tr><td>a nocturnal predator</td><td>夜间捕食者</td></tr><tr><td>nocturnal vision</td><td>夜间视力</td></tr><tr><td>become nocturnal</td><td>转为夜行</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the activity levels of a nocturnal mammal over 24 hours.</p><blockquote><p>该图显示了一种夜行哺乳动物在 24 小时内的活动水平。</p></blockquote><p><strong>Writing Task 2</strong> Street lighting turns night into a permanent dusk, and for nocturnal species that never see true darkness, feeding and breeding cycles break down.</p><blockquote><p>路灯把夜晚变成永久的黄昏，对从未见过真正黑夜的夜行物种来说，取食与繁殖周期就此崩坏。</p></blockquote><p><strong>Speaking</strong> My cat is nocturnal, which means three in the morning is her peak performance time.</p><blockquote><p>我的猫是夜行动物，也就是说凌晨三点是它的巅峰时段。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>night-time</td><td>夜间的</td><td>描述时间，不指习性</td></tr><tr><td>crepuscular</td><td>晨昏活动的</td><td>只在黎明黄昏活动，专业词</td></tr><tr><td>diurnal</td><td>昼行的</td><td>与 nocturnal 相对</td></tr><tr><td>dark-loving</td><td>喜暗的</td><td>描述性说法，非术语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>nox / noct-</em>（夜）+ -urnal（属于……的）</li><li><strong>Family:</strong> nocturnal 夜行的 / diurnal 昼行的 / equinox 昼夜平分（同源 nox）/ nocturne 夜曲</li><li><strong>Memory Tip:</strong> noct- 是&quot;夜&quot;：nocturnal 夜行、nocturne 夜曲、equinox 昼夜等长。三个词一记，noct- 就再也忘不掉。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>反义词是 <strong>diurnal</strong>（昼行），不是 <s>anti-nocturnal</s>。</li><li>拼写 noc-turn-al，注意中间的 t 与 r 顺序：nocturnal。</li><li>修饰名词作定语：nocturnal <strong>animals</strong> ✔ / <s>animals are nocturnal</s> 也对，但位置别混。</li></ul></div><div class="vocab-card"><h2 id="dormant" tabindex="-1"><a class="header-anchor" href="#dormant"><span>Dormant</span></a></h2><p class="vc-meta"><strong>/ˈdɔːmənt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>休眠的，蛰伏的（动植物）</li><li>潜伏的，暂不活动的（火山、能力）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a dormant volcano</td><td>休眠火山</td></tr><tr><td>lie dormant</td><td>处于休眠状态</td></tr><tr><td>dormant seeds</td><td>休眠种子</td></tr><tr><td>dormant season</td><td>休眠期</td></tr><tr><td>remain dormant for years</td><td>休眠多年</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how long the seeds remained dormant under each storage condition.</p><blockquote><p>该图显示了各储藏条件下种子保持休眠的时间。</p></blockquote><p><strong>Writing Task 2</strong> Some seeds lie dormant for decades and germinate only after a fire, which means suppressing every fire can quietly erase a whole plant community.</p><blockquote><p>有些种子休眠数十年，只在火灾之后才萌发，这意味着扑灭所有火灾会悄悄抹去整个植物群落。</p></blockquote><p><strong>Speaking</strong> The app has been dormant on my phone for two years and I still won&#39;t delete it.</p><blockquote><p>那个应用在我手机里躺了两年，我还是不肯删。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>inactive</td><td>不活跃的</td><td>通用，不含生物休眠机制</td></tr><tr><td>hibernating</td><td>冬眠中的</td><td>特指冬季的低温休眠</td></tr><tr><td>latent</td><td>潜伏的</td><td>强调存在但未显现</td></tr><tr><td>idle</td><td>闲置的</td><td>多用于机器、设备</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>dormire</em>（睡）</li><li><strong>Family:</strong> dormitory 宿舍 / dormant 休眠的 / dormouse 睡鼠</li><li><strong>Memory Tip:</strong> dorm- 是&quot;睡&quot;：dormitory 宿舍（睡觉的地方）、dormouse 睡鼠、dormant 休眠。一看到 dorm 就想&quot;睡&quot;，三个词全通。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>dormant（休眠）≠ extinct（灭绝）：火山休眠仍可能再喷。</li><li>动词搭配是 <strong>lie dormant</strong>，不用 <s>stay dormantly</s>。</li><li>拼写结尾是 <strong>-mant</strong>，不是 -ment：<s>dorment</s> ✘</li></ul></div><div class="vocab-card"><h2 id="hibernation" tabindex="-1"><a class="header-anchor" href="#hibernation"><span>Hibernation</span></a></h2><p class="vc-meta"><strong>/ˌhaɪbəˈneɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>冬眠；（喻）长期蛰伏</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>go into hibernation</td><td>进入冬眠</td></tr><tr><td>emerge from hibernation</td><td>从冬眠中醒来</td></tr><tr><td>winter hibernation</td><td>冬季冬眠</td></tr><tr><td>hibernation period</td><td>冬眠期</td></tr><tr><td>a hibernation site</td><td>冬眠场所</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how body temperature and heart rate fall during hibernation.</p><blockquote><p>该图显示了冬眠期间体温与心率如何下降。</p></blockquote><p><strong>Writing Task 2</strong> Hibernation is not sleep but a controlled shutdown: an animal may drop its heart rate to a few beats a minute and survive on stored fat for months.</p><blockquote><p>冬眠不是睡眠，而是一次受控的&quot;停机&quot;：动物可把心率降到每分钟几次，靠储存的脂肪存活数月。</p></blockquote><p><strong>Speaking</strong> I go into a kind of hibernation every January and emerge in March, slightly confused.</p><blockquote><p>我每年一月都进入某种冬眠，三月出来时还有点迷糊。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dormancy</td><td>休眠</td><td>更宽，含种子与夏眠</td></tr><tr><td>aestivation</td><td>夏眠</td><td>高温干旱期的休眠，与冬眠相对</td></tr><tr><td>torpor</td><td>蛰伏</td><td>短期降低体温代谢，专业词</td></tr><tr><td>sleep</td><td>睡眠</td><td>生理状态，与冬眠机制不同</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>hibernus</em>（冬天的）</li><li><strong>Family:</strong> hibernate 冬眠 / hibernal 冬季的 / hibernator 冬眠动物</li><li><strong>Memory Tip:</strong> 与西班牙语 <em>invierno</em>、法语 <em>hiver</em>（冬天）同源。夏眠叫 aestivation（aestas 夏），一冬一夏成对记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>冬眠是 hibernation，夏眠是 <strong>aestivation</strong>，写作别混。</li><li>动词形式 <strong>hibernate</strong>：Bears <strong>hibernate</strong>. ✔ / <s>Bears hibernation.</s> ✘</li><li>拼写 hi-ber-na-tion，注意中间是 -ber- 不是 -bra-。</li></ul></div><div class="vocab-card"><h2 id="bite" tabindex="-1"><a class="header-anchor" href="#bite"><span>Bite</span></a></h2><p class="vc-meta"><strong>/baɪt/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>咬，叮（动词）</li><li>咬伤；一口；（鱼）上钩（名词）</li><li>（喻）产生效果，刺痛</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>bite into ...</td><td>咬进……</td></tr><tr><td>a snake bite</td><td>蛇咬伤</td></tr><tr><td>take a bite</td><td>咬一口</td></tr><tr><td>bite the hand that feeds you</td><td>恩将仇报</td></tr><tr><td>insect bites</td><td>虫咬</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of hospital visits for animal bites in each region.</p><blockquote><p>该图显示了各地区因动物咬伤就诊的人数。</p></blockquote><p><strong>Writing Task 2</strong> Retaliatory killing after a livestock attack is one of the main reasons large predators are still shot, even where they are legally protected.</p><blockquote><p>牲畜被咬后的报复性猎杀，是大型捕食者即便受法律保护仍被射杀的主要原因之一。</p></blockquote><p><strong>Speaking</strong> The puppy bites everything — shoes, hands, the furniture — but somehow never its own toys.</p><blockquote><p>小狗什么都咬，鞋、手、家具，偏偏不咬自己的玩具。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sting</td><td>蜇</td><td>蜂、蝎用尾针刺，不是咬</td></tr><tr><td>nip</td><td>轻咬</td><td>力度小，多指狗或寒冷</td></tr><tr><td>gnaw</td><td>啃</td><td>反复啃磨，鼠类常用</td></tr><tr><td>chew</td><td>咀嚼</td><td>口腔内的研磨动作</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>bītan</em></li><li><strong>Family:</strong> bite 咬 / biting 刺骨的；尖刻的 / bitter 苦的（同源&quot;咬&quot;）/ beetle 甲虫（&quot;咬人的虫&quot;）</li><li><strong>Memory Tip:</strong> 同源的 bitter 原义&quot;咬人的味道&quot;，beetle 原义&quot;会咬的虫&quot;。一条&quot;咬&quot;的线索串起三个词，比单记高效。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式 <strong>bit</strong>、过去分词 <strong>bitten</strong>：<s>bited</s> ✘</li><li>蜂类用 <strong>sting</strong>，不用 bite；蚊子用 bite 或 sting 都可。</li><li>&quot;咬一口&quot;是 take a bite，不是 <s>eat a bite</s>。</li></ul></div><div class="vocab-card"><h2 id="sting" tabindex="-1"><a class="header-anchor" href="#sting"><span>Sting</span></a></h2><p class="vc-meta"><strong>/stɪŋ/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蜇，刺（蜂、蝎、植物）（动词）</li><li>刺痛，使难受（情感）</li><li>螫针；刺伤（名词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>be stung by a bee</td><td>被蜜蜂蜇</td></tr><tr><td>a sting</td><td>螫针；刺痛</td></tr><tr><td>sting operation</td><td>钓鱼执法（警方）</td></tr><tr><td>a stinging remark</td><td>尖刻的话</td></tr><tr><td>sting sb into action</td><td>刺激某人行动</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of people treated for insect stings each summer.</p><blockquote><p>该图显示了每年夏天因昆虫蜇伤接受治疗的人数。</p></blockquote><p><strong>Writing Task 2</strong> A bee dies after it stings, which is why stinging is a last resort and why disturbing a hive is so costly for the colony.</p><blockquote><p>蜜蜂蜇人后会死去，因此蜇刺是最后手段，也正因如此惊扰蜂巢对整群代价极高。</p></blockquote><p><strong>Speaking</strong> I stepped on a bee barefoot, and the sting hurt for two days.</p><blockquote><p>我赤脚踩到一只蜜蜂，那一下疼了两天。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bite</td><td>咬</td><td>用口器咬，sting 用尾针</td></tr><tr><td>prick</td><td>刺</td><td>尖锐物轻刺，不含毒液</td></tr><tr><td>smart</td><td>刺痛</td><td>书面，多形容伤口</td></tr><tr><td>hurt</td><td>使疼痛</td><td>最泛，无&quot;针刺&quot;意象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>stingan</em>（刺）</li><li><strong>Family:</strong> sting 蜇 / stinger 螫针 / stingy 吝啬的（不同源，拼写相近）/ distinct（同源&quot;刺开&quot;）</li><li><strong>Memory Tip:</strong> 注意 stingy（吝啬）与 sting 无词源关系，只是一个&quot;扎手&quot;的联想。分清这一点能避免把&quot;蜇&quot;与&quot;小气&quot;混为一谈。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式/过去分词 <strong>stung</strong>：<s>stinged</s> ✘</li><li>蜂蜇是 sting，蛇咬是 bite，动物不同动词不同。</li><li>&quot;钓鱼执法&quot;是 <strong>sting operation</strong>，固定搭配。</li></ul></div><div class="vocab-card"><h2 id="bark" tabindex="-1"><a class="header-anchor" href="#bark"><span>Bark</span></a></h2><p class="vc-meta"><strong>/bɑːk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>狗叫声，吠声（名词）</li><li>吠，叫（动词）</li><li>树皮（同形异义，名词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>bark at ...</td><td>朝……吠</td></tr><tr><td>a dog&#39;s bark</td><td>狗叫声</td></tr><tr><td>tree bark</td><td>树皮</td></tr><tr><td>bark up the wrong tree</td><td>找错对象</td></tr><tr><td>its bark is worse than its bite</td><td>嘴上凶，实则无害</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how often each breed barked during a standard noise test.</p><blockquote><p>该图显示了在标准噪声测试中各犬种吠叫的频率。</p></blockquote><p><strong>Writing Task 2</strong> A dog that barks at every walker makes an entire footpath feel unsafe, and the response is usually a ban rather than training.</p><blockquote><p>对每个路过者都吠的狗会让整条步道显得不安全，而回应通常是禁令，而非训练。</p></blockquote><p><strong>Speaking</strong> The neighbour&#39;s dog barks at the postman, the bin lorry, and occasionally the wind.</p><blockquote><p>邻居的狗朝邮递员、垃圾车叫，偶尔也朝风叫。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>howl</td><td>长嚎</td><td>狼、犬的延长哀鸣</td></tr><tr><td>growl</td><td>低吼</td><td>威胁性的低沉声</td></tr><tr><td>yelp</td><td>尖吠</td><td>短促高音，多因疼痛</td></tr><tr><td>snap</td><td>猛咬</td><td>伴随短促叫声的攻击动作</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>beorcan</em>（吠）；&quot;树皮&quot;义来自古诺斯语 <em>bǫrkr</em></li><li><strong>Family:</strong> bark 吠；树皮 / barking 吠叫 / barkless 不吠的</li><li><strong>Memory Tip:</strong> 一句话记住两义：&quot;狗对着树叫&quot;——bark at the tree，狗在吠，树有树皮。同形异义靠语境分开，不必强记词源。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>吠叫是不及物，需带 at：The dog barked <strong>at</strong> me. ✔</li><li>&quot;树皮&quot;与&quot;吠&quot;同形，学术文本描述树皮时可加 tree bark 明确。</li><li>习语 its bark is worse than its bite 意为&quot;虚张声势&quot;，别按字面理解。</li></ul></div><div class="vocab-card"><h2 id="roar" tabindex="-1"><a class="header-anchor" href="#roar"><span>Roar</span></a></h2><p class="vc-meta"><strong>/rɔː(r)/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（狮、虎等）吼叫；（人）大喊</li><li>（机器、火、风）轰鸣</li><li>吼声；轰鸣声</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a lion&#39;s roar</td><td>狮吼</td></tr><tr><td>roar with laughter</td><td>哄堂大笑</td></tr><tr><td>roar past</td><td>轰然驶过</td></tr><tr><td>the roar of the crowd</td><td>人群的喧嚣</td></tr><tr><td>roar its approval</td><td>大声表示赞同</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how far a lion&#39;s roar can be heard under different conditions.</p><blockquote><p>该图显示了在不同条件下狮吼能传多远。</p></blockquote><p><strong>Writing Task 2</strong> A lion&#39;s roar carries for eight kilometres, which is less a threat than a notice: this territory is taken.</p><blockquote><p>狮吼可传出八公里，与其说是威胁，不如说是一份告示：这片领地已有主。</p></blockquote><p><strong>Speaking</strong> The crowd roared when the elephant finally came out, and she stopped and looked straight at us.</p><blockquote><p>大象终于出来时人群轰然欢呼，它停下来直直看着我们。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>bellow</td><td>怒吼</td><td>多指人低沉的大声</td></tr><tr><td>howl</td><td>长嚎</td><td>狼、风的延绵声</td></tr><tr><td>thunder</td><td>轰隆</td><td>只用于自然或巨大声响</td></tr><tr><td>shout</td><td>喊叫</td><td>人的普通大声说话</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>rārian</em>，拟声词</li><li><strong>Family:</strong> roar 吼叫 / roaring 轰鸣的；兴旺的 / uproar 喧嚣（up + roar）</li><li><strong>Memory Tip:</strong> uproar（骚动）就是&quot;声音轰起来&quot;——roar 加 up，画面很足。 roaring trade 表示&quot;生意兴隆&quot;，同样是&quot;热闹&quot;的引申。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式与过去分词都是 <strong>roared</strong>，不双写 r。</li><li>&quot;哄堂大笑&quot;是 <strong>roar with laughter</strong>，介词用 with。</li><li>拼写 roar，注意 oa 顺序，别写 <s>raor</s>。</li></ul></div><div class="vocab-card"><h2 id="rub" tabindex="-1"><a class="header-anchor" href="#rub"><span>Rub</span></a></h2><p class="vc-meta"><strong>/rʌb/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>擦，摩擦；揉搓</li><li>涂抹（rub sth on/into）</li><li>磨损，磨痛</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rub against ...</td><td>在……上摩擦</td></tr><tr><td>rub its eyes</td><td>揉眼睛</td></tr><tr><td>rub sth into the skin</td><td>把……揉进皮肤</td></tr><tr><td>rub along</td><td>勉强相处</td></tr><tr><td>rub off</td><td>擦掉；因接触而沾上</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows where the animal rubs against trees to mark its territory.</p><blockquote><p>该示意图展示了这种动物在树上的哪些位置摩擦以标记领地。</p></blockquote><p><strong>Writing Task 2</strong> Bears rub their backs against the same trunks year after year, and the resulting scars are a record of how the population uses the forest.</p><blockquote><p>熊年复一年在同一批树干上蹭背，留下的伤痕记录了种群如何使用这片森林。</p></blockquote><p><strong>Speaking</strong> The cat rubs against my legs every time I open the fridge, which is not a coincidence.</p><blockquote><p>每次我开冰箱猫就来蹭我的腿，这绝非巧合。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>scrub</td><td>刷洗</td><td>用力擦洗，多用于清洁</td></tr><tr><td>wipe</td><td>擦拭</td><td>用布抹过表面</td></tr><tr><td>stroke</td><td>抚摸</td><td>轻柔单向动作</td></tr><tr><td>chafe</td><td>磨痛</td><td>强调摩擦造成损伤</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>rubben</em></li><li><strong>Family:</strong> rub 摩擦 / rubber 橡胶（原义&quot;擦的东西&quot;）/ rubbish 垃圾（同源&quot;碎屑&quot;）</li><li><strong>Memory Tip:</strong> rubber（橡胶）原义就是&quot;用来擦的东西&quot;——最早的橡皮。rubbish 是擦下来的&quot;碎屑&quot;。一条&quot;擦&quot;的线串起两个高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>双写 b 加词尾：<strong>rubbed / rubbing</strong> ✔</li><li>&quot;把药膏揉进去&quot;用 rub <strong>into</strong>，不是 <s>rub in</s> 单独使用时的意思（后者也可，但搭配要注意）。</li><li>拼写 rub，别与 <s>rob</s>（抢劫）混。</li></ul></div><div class="vocab-card"><h2 id="creep" tabindex="-1"><a class="header-anchor" href="#creep"><span>Creep</span></a></h2><p class="vc-meta"><strong>/kriːp/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>悄悄移动，蹑手蹑脚地走</li><li>蔓延，爬行（植物、雾、感觉）</li><li>（皮肤）发麻起鸡皮疙瘩</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>creep up on ...</td><td>悄悄接近……</td></tr><tr><td>creep along</td><td>缓慢移动</td></tr><tr><td>creep into ...</td><td>慢慢渗入……</td></tr><tr><td>make one&#39;s skin creep</td><td>让人毛骨悚然</td></tr><tr><td>creeping plants</td><td>蔓生植物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the city crept outwards between 1950 and 2020.</p><blockquote><p>该地图显示了 1950 至 2020 年间城市如何向外蔓延。</p></blockquote><p><strong>Writing Task 2</strong> Suburbs creep into farmland one field at a time, and nobody notices until the corridor that connected two reserves is gone.</p><blockquote><p>郊区一片田一片田地蚕食农田，直到连接两个保护区的廊道消失，人们才察觉。</p></blockquote><p><strong>Speaking</strong> I crept downstairs at three in the morning to get water and stepped on the cat.</p><blockquote><p>我凌晨三点蹑手蹑脚下楼拿水，踩到了猫。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>crawl</td><td>爬行</td><td>身体贴地移动，速度慢</td></tr><tr><td>sneak</td><td>溜</td><td>强调不被发现，多用于人</td></tr><tr><td>slink</td><td>溜走</td><td>带羞愧或鬼祟意味</td></tr><tr><td>spread</td><td>蔓延</td><td>强调范围扩大，不含悄悄义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>crēopan</em></li><li><strong>Family:</strong> creep 爬行 / creeper 蔓生植物 / creepy 令人毛骨悚然的</li><li><strong>Memory Tip:</strong> creepy（毛骨悚然）来自&quot;皮肤上有东西在爬&quot;的感觉。一个形容词把 creep 的&quot;悄悄爬&quot;与&quot;发麻&quot;两义同时锁住。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式/过去分词 <strong>crept</strong>：<s>creeped</s> ✘</li><li>&quot;悄悄接近&quot;是 creep <strong>up on</strong>，介词不能省。</li><li>动词 creep 与名词 creeper（蔓生植物）词性不同，别混。</li></ul></div><div class="vocab-card"><h2 id="crawl" tabindex="-1"><a class="header-anchor" href="#crawl"><span>Crawl</span></a></h2><p class="vc-meta"><strong>/krɔːl/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>爬，爬行（身体贴地）</li><li>缓慢移动（交通）</li><li>巴结，谄媚（crawl to sb）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>crawl along</td><td>缓慢爬行</td></tr><tr><td>crawl out of ...</td><td>从……爬出</td></tr><tr><td>traffic crawls</td><td>车流缓慢</td></tr><tr><td>crawl on all fours</td><td>四肢着地爬</td></tr><tr><td>crawl with ...</td><td>爬满……</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a turtle crawls from the nest to the sea.</p><blockquote><p>该示意图展示了海龟如何从巢爬向大海。</p></blockquote><p><strong>Writing Task 2</strong> Once hatchlings leave the nest, they must crawl across open sand where every shadow is a predator, and most do not reach the water.</p><blockquote><p>幼龟一离开巢就必须爬过开阔沙地，那里每一道影子都是捕食者，多数活不到水边。</p></blockquote><p><strong>Speaking</strong> Traffic was crawling for an hour because of one broken-down lorry.</p><blockquote><p>因为一辆抛锚的货车，车流爬了一小时。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>creep</td><td>悄悄移动</td><td>强调轻、不被察觉</td></tr><tr><td>climb</td><td>攀爬</td><td>向上攀登，需抓握</td></tr><tr><td>scramble</td><td>攀爬</td><td>手脚并用、动作急促</td></tr><tr><td>slither</td><td>滑行</td><td>蛇类的贴地移动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺斯语 <em>krafla</em>（抓爬）</li><li><strong>Family:</strong> crawl 爬 / crawler 爬行者；履带 / crawlspace 低矮夹层</li><li><strong>Memory Tip:</strong> 爬泳叫 <strong>front crawl</strong>——手臂像爬行一样轮流前伸。游泳时想到&quot;爬&quot;，动作反而更顺。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;爬满&quot;用 be <strong>crawling with</strong>：The log was crawling <strong>with</strong> ants. ✔</li><li>crawl 与 climb 不同：crawl 贴地，climb 向上。</li><li>过去式 crawled，不双写 l。</li></ul></div><div class="vocab-card"><h2 id="track" tabindex="-1"><a class="header-anchor" href="#track"><span>Track</span></a></h2><p class="vc-meta"><strong>/træk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>足迹，踪迹；小径；轨道</li><li>追踪，跟踪（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>animal tracks</td><td>动物足迹</td></tr><tr><td>keep track of ...</td><td>掌握……的动态</td></tr><tr><td>track an animal</td><td>追踪动物</td></tr><tr><td>on the right track</td><td>方向正确</td></tr><tr><td>lose track of ...</td><td>失去……的线索</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the tracks recorded by radio-collared animals over one year.</p><blockquote><p>该地图显示了一年中被无线电项圈标记的动物所记录的移动轨迹。</p></blockquote><p><strong>Writing Task 2</strong> Satellite tags allow researchers to track migrating birds in real time, but the data also reveals how often their stopover sites have already been built over.</p><blockquote><p>卫星标签让研究者能实时追踪迁徙鸟类，但数据也揭示出它们的中途停歇地有多少已被建筑覆盖。</p></blockquote><p><strong>Speaking</strong> The dog found a track in the mud and followed it for half a kilometre.</p><blockquote><p>狗在泥里发现一串足迹，跟了半公里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>trace</td><td>痕迹</td><td>强调遗留的微小迹象</td></tr><tr><td>trail</td><td>踪迹；小径</td><td>强调连续的一串痕迹</td></tr><tr><td>path</td><td>小路</td><td>只指路线，不含追踪义</td></tr><tr><td>monitor</td><td>监测</td><td>强调持续观察，不涉足迹</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>trac</em>（足迹）</li><li><strong>Family:</strong> track 足迹；轨道 / tracker 追踪器 / tracksuit 运动服 / soundtrack 配乐</li><li><strong>Memory Tip:</strong> track 由&quot;足迹&quot;扩展到&quot;轨道&quot;（火车走的线），再到&quot;曲目&quot;（唱片上的轨道）。抓住&quot;一条线&quot;这个核心，多义自动归位。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;掌握动态&quot;是 keep track <strong>of</strong>，介词不能省。</li><li>track 与 trace 不同：track 是实体足迹或轨迹，trace 是微量痕迹。</li><li>拼写 track，别与 <s>truck</s> 混。</li></ul></div><div class="vocab-card"><h2 id="trace" tabindex="-1"><a class="header-anchor" href="#trace"><span>Trace</span></a></h2><p class="vc-meta"><strong>/treɪs/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>痕迹，微量</li><li>追踪，追溯；描摹（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>trace elements</td><td>微量元素</td></tr><tr><td>without trace</td><td>无影无踪</td></tr><tr><td>trace the origin of ...</td><td>追溯……的起源</td></tr><tr><td>trace back to ...</td><td>追溯到……</td></tr><tr><td>a trace of ...</td><td>一丝……</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram traces the path of a chemical from farmland to the sea.</p><blockquote><p>该示意图追溯了一种化学物质从农田到海洋的路径。</p></blockquote><p><strong>Writing Task 2</strong> Traces of plastic have been found in animals from the deepest trench, which means no habitat on earth is now untouched.</p><blockquote><p>在最深海沟的动物体内也发现了塑料的痕迹，这意味着地球上已没有未被触及的栖息地。</p></blockquote><p><strong>Speaking</strong> There wasn&#39;t a trace of the cake left when I got home — not a crumb.</p><blockquote><p>我回家时蛋糕一点痕迹都没剩，一粒渣都没有。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>track</td><td>足踪</td><td>实体足迹，更具体</td></tr><tr><td>remnant</td><td>残余</td><td>强调剩下的一部分</td></tr><tr><td>vestige</td><td>遗迹</td><td>书面，指几乎消失的残存</td></tr><tr><td>trail</td><td>踪迹</td><td>连续的一串线索</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>tracier</em>，源自拉丁 <em>trahere</em>（拉、拖）</li><li><strong>Family:</strong> trace 痕迹 / tract 地带；小册子（同源）/ attract 吸引（&quot;拉向&quot;）/ contract 合同（&quot;拉到一起&quot;）</li><li><strong>Memory Tip:</strong> 词根 trahere 是&quot;拉&quot;：trace 是&quot;拉出一条线来追溯&quot;，attract 是&quot;拉过去吸引&quot;，contract 是&quot;拉到一起签约&quot;。一个词根铺开一大片。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;追溯到&quot;是 trace back <strong>to</strong>，back 不能省。</li><li>&quot;无影无踪&quot;是 <strong>without trace</strong>，不加冠词。</li><li>拼写 trace，别与 <s>trance</s>（恍惚）混。</li></ul></div><div class="vocab-card"><h2 id="alternate" tabindex="-1"><a class="header-anchor" href="#alternate"><span>Alternate</span></a></h2><p class="vc-meta"><strong>/ɔːlˈtɜːnət/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>交替的，间隔的（形容词，读 /ɔːlˈtɜːnət/）</li><li>轮流，交替（动词，读 /ˈɔːltəneɪt/）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>alternate between A and B</td><td>在 A 与 B 之间交替</td></tr><tr><td>on alternate days</td><td>隔天</td></tr><tr><td>alternate layers</td><td>交错的层次</td></tr><tr><td>alternate generations</td><td>世代交替</td></tr><tr><td>alternating current</td><td>交流电</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows alternating periods of activity and rest across the 24-hour cycle.</p><blockquote><p>该图显示了 24 小时周期中活动与休息交替出现的时段。</p></blockquote><p><strong>Writing Task 2</strong> Some species alternate between two hosts to complete their life cycle, so removing either one collapses the whole system.</p><blockquote><p>有些物种在两种宿主之间交替以完成生活史，因此移除其中任何一种都会使整个系统崩溃。</p></blockquote><p><strong>Speaking</strong> We alternate who cooks, which works well until neither of us wants to.</p><blockquote><p>我们轮流做饭，效果不错，直到两个都不想做的那个晚上。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rotate</td><td>轮换</td><td>强调按顺序循环</td></tr><tr><td>switch</td><td>切换</td><td>强调一次性转换</td></tr><tr><td>take turns</td><td>轮流</td><td>口语，用于人</td></tr><tr><td>successive</td><td>连续的</td><td>只表顺序，不含交替</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>alternare</em>（轮流），源自 <em>alter</em>（另一个）</li><li><strong>Family:</strong> alternative 替代的 / alter 改变 / altruism 利他（同源&quot;他人&quot;）/ alien 外来的</li><li><strong>Memory Tip:</strong> alter 是&quot;另一个&quot;：alternate 是两个&quot;另一个&quot;轮流；alternative 是&quot;另一个可选方案&quot;；alter 是&quot;变成另一个&quot;。三词一源，义项自然分开。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词与形容词重音不同：形容词 /ɔːlˈtɜːnət/，动词 /ˈɔːltəneɪt/。</li><li>alternate（交替）≠ alternative（替代的）：alternate days 是隔天，alternative plan 是备选方案。</li><li>拼写 alter-nate，注意 -nate 不是 <s>-net</s>。</li></ul></div><div class="vocab-card"><h2 id="devour" tabindex="-1"><a class="header-anchor" href="#devour"><span>Devour</span></a></h2><p class="vc-meta"><strong>/dɪˈvaʊə(r)/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>吞食，狼吞虎咽地吃</li><li>吞没，吞噬（火、黑暗）</li><li>如饥似渴地阅读</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>devour its prey</td><td>吞食猎物</td></tr><tr><td>devour a book</td><td>一口气读完一本书</td></tr><tr><td>be devoured by flames</td><td>被火焰吞没</td></tr><tr><td>devour everything on the plate</td><td>把盘子里的东西吃光</td></tr><tr><td>devour information</td><td>大量吸收信息</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares how much a growing chick devours each day over its first month.</p><blockquote><p>该图比较了雏鸟在第一个月内每天吞食的食物量。</p></blockquote><p><strong>Writing Task 2</strong> A single swarm can devour a field in hours, and the loss is total rather than partial.</p><blockquote><p>一群蝗虫几小时就能吞掉一片田，损失是全毁而非部分。</p></blockquote><p><strong>Speaking</strong> He devoured the entire series in a weekend and then complained there was nothing left.</p><blockquote><p>他一个周末刷完了整部剧，然后抱怨没得看了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>consume</td><td>消耗</td><td>中性，正式，不含&quot;贪婪&quot;</td></tr><tr><td>gobble</td><td>狼吞虎咽</td><td>口语，拟声感强</td></tr><tr><td>swallow</td><td>吞下</td><td>只指动作，不含急切</td></tr><tr><td>absorb</td><td>吸收</td><td>抽象义接近，无&quot;吃&quot;的画面</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>devorare</em>：de-（向下）+ vorare（吞）</li><li><strong>Family:</strong> voracious 贪吃的 / carnivore 食肉动物 / herbivore 食草动物 / omnivore 杂食动物</li><li><strong>Memory Tip:</strong> vorare 是&quot;吞&quot;：devour 吞下、voracious 贪婪的、-vore 结尾的三个&quot;食性&quot;词全在这一族。一个词根统管&quot;吃&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>devour 带&quot;急切、贪婪&quot;色彩，中性描述进食宜用 eat / consume。</li><li>拼写 dev-our，不是 <s>devower</s>。</li><li>被动语态常用于&quot;被吞没&quot;：The house was <strong>devoured</strong> by fire. ✔</li></ul></div>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};